An interviewer recently asked me two Java SDET coding questions.
Section 1: Code Optimization
1. Test Log Filtering & Parsing Optimization
Problem Statement: A test automation reporting script takes too long to filter out known flaky test signatures from a large array of failure logs because it uses nested linear searches with string concatenation, resulting in high CPU overhead.

Initial Inefficient Code:
import java.util.ArrayList;
import java.util.List;

public class LogFilterInefficient {
    public static List<String> findKnownFailures(List<String> logs, List<String> knownSignatures) {
        List<String> filteredLogs = new ArrayList<>();
        // Inefficient O(N * M) nested scan
        for (String log : logs) {
            boolean isKnown = false;
            for (String sig : knownSignatures) {
                if (log.contains(sig)) {
                    isKnown = true;
                    break;
                }
            }
            if (!isKnown) {
                filteredLogs.add(log);
            }
        }
        return filteredLogs;
    }

    public static void main(String[] args) {
        List<String> sampleLogs = new ArrayList<>();
        for (int i = 0; i < 5000; i++) {
            sampleLogs.add("Error: Timeout at step " + i);
        }
        sampleLogs.add("Critical DB crash");
        List<String> signatures = new ArrayList<>();
        signatures.add("Critical DB crash");
        signatures.add("Timeout at step 4999");
        long start = System.currentTimeMillis();
        List<String> result = findKnownFailures(sampleLogs, signatures);
        long end = System.currentTimeMillis();
        System.out.println("Initial execution time: " + (end - start) + " ms. Filtered count: " + result.size());
    }
}

